   1→import { useState, useCallback, useMemo, useEffect } from "react";
   2→import type {
   3→  ActionFunctionArgs,
   4→  HeadersFunction,
   5→  LoaderFunctionArgs,
   6→} from "react-router";
   7→import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
   8→import { useAppBridge } from "@shopify/app-bridge-react";
   9→import { authenticate } from "../shopify.server";
  10→import { boundary } from "@shopify/shopify-app-react-router/server";
  11→import db from "../db.server";
  12→import { getShopSubscription } from "../billing.server";
  13→import { PLAN_LIMITS, UNLIMITED } from "../plans";
  14→import {
  15→  Page,
  16→  Layout,
  17→  Card,
  18→  BlockStack,
  19→  InlineStack,
  20→  Text,
  21→  Button,
  22→  TextField,
  23→  Select,
  24→  Modal,
  25→  DataTable,
  26→  EmptyState,
  27→  Divider,
  28→  Box,
  29→  Tooltip,
  30→  Icon,
  31→  Banner,
  32→  Pagination,
  33→  InlineGrid,
  34→} from "@shopify/polaris";
  35→import {
  36→  SearchIcon,
  37→  DeleteIcon,
  38→  PlusIcon,
  39→  EmailIcon,
  40→} from "@shopify/polaris-icons";
  41→
  42→const PAGE_SIZE = 10;
  43→
  44→export const loader = async ({ request }: LoaderFunctionArgs) => {
  45→  const { session } = await authenticate.admin(request);
  46→  const shop = session.shop;
  47→
  48→  const [entries, subscription] = await Promise.all([
  49→    db.waitlistEntry.findMany({
  50→      where: { shop },
  51→      orderBy: { createdAt: "desc" },
  52→    }),
  53→    getShopSubscription(shop),
  54→  ]);
  55→
  56→  const stats = {
  57→    total: entries.length,
  58→    waiting: entries.filter((e) => e.status === "waiting").length,
  59→    accepted: entries.filter((e) => e.status === "accepted").length,
  60→    rejected: entries.filter((e) => e.status === "rejected").length,
  61→    notified: entries.filter((e) => e.status === "notified").length,
  62→    converted: entries.filter((e) => e.status === "converted").length,
  63→    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
  64→  };
  65→
  66→  return { entries, stats, subscription };
  67→};
  68→
  69→export const action = async ({ request }: ActionFunctionArgs) => {
  70→  const { session } = await authenticate.admin(request);
  71→  const shop = session.shop;
  72→  const formData = await request.formData();
  73→  const intent = formData.get("intent");
  74→
  75→  if (intent === "add") {
  76→    const email = String(formData.get("email") || "").trim().toLowerCase();
  77→    const zipCode = String(formData.get("zipCode") || "")
  78→      .trim()
  79→      .toUpperCase();
  80→    const note = String(formData.get("note") || "").trim() || null;
  81→
  82→    if (!email || !zipCode) return { error: "Email and zip code are required." };
  83→
  84→    const subscription = await getShopSubscription(shop);
  85→    const limits = PLAN_LIMITS[subscription.planTier];
  86→
  87→    if (limits.maxWaitlist === 0) {
  88→      return { error: "Your current plan does not include waitlist access. Upgrade to Starter or higher." };
  89→    }
  90→
  91→    if (limits.maxWaitlist < UNLIMITED) {
  92→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
  93→      if (currentCount >= limits.maxWaitlist) {
  94→        return { error: `You have reached the ${limits.maxWaitlist}-entry waitlist limit on your ${limits.label} plan. Upgrade to Pro for unlimited entries.` };
  95→      }
  96→    }
  97→
  98→    try {
  99→      await db.waitlistEntry.create({
 100→        data: { shop, email, zipCode, note },
 101→      });
 102→      return { success: true, action: "added" };
 103→    } catch {
 104→      return { error: "This email is already on the waitlist for this zip code." };
 105→    }
 106→  }
 107→
 108→  if (intent === "delete") {
 109→    const id = String(formData.get("id"));
 110→    try {
 111→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 112→      if (!existing) return { error: "Entry not found." };
 113→      await db.waitlistEntry.delete({ where: { id } });
 114→      return { success: true, action: "deleted" };
 115→    } catch {
 116→      return { error: "Failed to delete entry." };
 117→    }
 118→  }
 119→
 120→  if (intent === "update-status") {
 121→    const id = String(formData.get("id"));
 122→    const status = String(formData.get("status"));
 123→    try {
 124→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 125→      if (!existing) return { error: "Entry not found." };
 126→      await db.waitlistEntry.update({ where: { id }, data: { status } });
 127→      return { success: true, action: "updated" };
 128→    } catch {
 129→      return { error: "Failed to update entry status." };
 130→    }
 131→  }
 132→
 133→  if (intent === "bulk-notify") {
 134→    const zipCode = String(formData.get("zipCode") || "")
 135→      .trim()
 136→      .toUpperCase();
 137→    if (!zipCode) return { error: "Zip code is required." };
 138→
 139→    const bulkNotifySub = await getShopSubscription(shop);
 140→    if (PLAN_LIMITS[bulkNotifySub.planTier].maxWaitlist < UNLIMITED) {
 141→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 142→    }
 143→
 144→    const updated = await db.waitlistEntry.updateMany({
 145→      where: { shop, zipCode, status: "waiting" },
 146→      data: { status: "notified" },
 147→    });
 148→
 149→    return {
 150→      success: true,
 151→      action: "bulk-notify",
 152→      count: updated.count,
 153→      zipCode,
 154→    };
 155→  }
 156→
 157→  if (intent === "notify-zip") {
 158→    const zipCode = String(formData.get("zipCode") || "").trim().toUpperCase();
 159→    if (!zipCode) return { error: "No ZIP code specified." };
 160→
 161→    const notifyZipSub = await getShopSubscription(shop);
 162→    if (PLAN_LIMITS[notifyZipSub.planTier].maxWaitlist < UNLIMITED) {
 163→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 164→    }
 165→
 166→    const entries = await db.waitlistEntry.findMany({
 167→      where: { shop, zipCode, status: "waiting" },
 168→      select: { id: true, email: true },
 169→    });
 170→
 171→    if (entries.length === 0) {
 172→      return { action: "notify-zip", zipCode, emails: [] as string[], count: 0 };
 173→    }
 174→
 175→    await db.waitlistEntry.updateMany({
 176→      where: { shop, zipCode, status: "waiting" },
 177→      data: { status: "notified" },
 178→    });
 179→
 180→    const emails = entries.map((e) => e.email);
 181→    return { action: "notify-zip", zipCode, emails, count: emails.length };
 182→  }
 183→
 184→  if (intent === "delete-all-notified") {
 185→    const deleted = await db.waitlistEntry.deleteMany({
 186→      where: { shop, status: "notified" },
 187→    });
 188→    return { success: true, action: "deleted-notified", count: deleted.count };
 189→  }
 190→
 191→  if (intent === "accept") {
 192→    const id = String(formData.get("id"));
 193→    const entry = await db.waitlistEntry.findUnique({ where: { id } });
 194→    if (!entry || entry.shop !== shop) {
 195→      return { error: "Entry not found." };
 196→    }
 197→
 198→    // Add the ZIP code to the allowed list
 199→    await db.zipCode.upsert({
 200→      where: { shop_zipCode: { shop, zipCode: entry.zipCode } },
 201→      create: {
 202→        shop,
 203→        zipCode: entry.zipCode,
 204→        type: "allowed",
 205→        isActive: true,
 206→        label: `Requested by ${entry.name || entry.email}`,
 207→      },
 208→      update: {
 209→        type: "allowed",
 210→        isActive: true,
 211→      },
 212→    });
 213→
 214→    // Mark the waitlist entry as accepted
 215→    await db.waitlistEntry.update({
 216→      where: { id },
 217→      data: { status: "accepted" },
 218→    });
 219→
 220→    return { success: true, action: "accepted", zipCode: entry.zipCode };
 221→  }
 222→
 223→  if (intent === "reject") {
 224→    const id = String(formData.get("id"));
 225→    try {
 226→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 227→      if (!existing) return { error: "Entry not found." };
 228→      await db.waitlistEntry.update({
 229→        where: { id },
 230→        data: { status: "rejected" },
 231→      });
 232→      return { success: true, action: "rejected" };
 233→    } catch {
 234→      return { error: "Failed to reject entry." };
 235→    }
 236→  }
 237→
 238→  return null;
 239→};
 240→
 241→type WaitlistEntry = {
 242→  id: string;
 243→  name: string | null;
 244→  email: string;
 245→  zipCode: string;
 246→  note: string | null;
 247→  status: string;
 248→  createdAt: string | Date;
 249→};
 250→
 251→export default function WaitlistPage() {
 252→  const { entries, stats, subscription } = useLoaderData<typeof loader>();
 253→  const fetcher = useFetcher<typeof action>();
 254→  const shopify = useAppBridge();
 255→  const navigate = useNavigate();
 256→
 257→  const limits = PLAN_LIMITS[subscription.planTier];
 258→  const isFreePlan = limits.maxWaitlist === 0;
 259→  const isStarterPlan = limits.maxWaitlist < UNLIMITED && limits.maxWaitlist > 0;
 260→
 261→  const [searchQuery, setSearchQuery] = useState("");
 262→  const [statusFilter, setStatusFilter] = useState("all");
 263→  const [currentPage, setCurrentPage] = useState(1);
 264→  const [addModalOpen, setAddModalOpen] = useState(false);
 265→  const [notifyModalOpen, setNotifyModalOpen] = useState(false);
 266→  const [notifyResultModalOpen, setNotifyResultModalOpen] = useState(false);
 267→  const [notifyResult, setNotifyResult] = useState<{
 268→    zipCode: string;
 269→    emails: string[];
 270→    count: number;
 271→  } | null>(null);
 272→  const [copySuccess, setCopySuccess] = useState(false);
 273→
 274→  // Form state
 275→  const [newEmail, setNewEmail] = useState("");
 276→  const [newZipCode, setNewZipCode] = useState("");
 277→  const [newNote, setNewNote] = useState("");
 278→  const [notifyZip, setNotifyZip] = useState("");
 279→
 280→  const actionError =
 281→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
 282→
 283→  useEffect(() => {
 284→    if (
 285→      fetcher.data &&
 286→      "action" in fetcher.data &&
 287→      fetcher.data.action === "notify-zip"
 288→    ) {
 289→      const data = fetcher.data as {
 290→        action: string;
 291→        zipCode: string;
 292→        emails: string[];
 293→        count: number;
 294→      };
 295→      setNotifyResult({ zipCode: data.zipCode, emails: data.emails, count: data.count });
 296→      setNotifyResultModalOpen(true);
 297→    }
 298→  }, [fetcher.data]);
 299→
 300→  const filteredEntries = useMemo(() => {
 301→    let filtered = entries as WaitlistEntry[];
 302→    if (searchQuery.trim()) {
 303→      const q = searchQuery.trim().toLowerCase();
 304→      filtered = filtered.filter(
 305→        (e) =>
 306→          e.email.toLowerCase().includes(q) ||
 307→          e.zipCode.toLowerCase().includes(q) ||
 308→          (e.note && e.note.toLowerCase().includes(q)),
 309→      );
 310→    }
 311→    if (statusFilter !== "all") {
 312→      filtered = filtered.filter((e) => e.status === statusFilter);
 313→    }
 314→    return filtered;
 315→  }, [entries, searchQuery, statusFilter]);
 316→
 317→  const totalPages = Math.max(1, Math.ceil(filteredEntries.length / PAGE_SIZE));
 318→  const paginatedEntries = useMemo(() => {
 319→    const start = (currentPage - 1) * PAGE_SIZE;
 320→    return filteredEntries.slice(start, start + PAGE_SIZE);
 321→  }, [filteredEntries, currentPage]);
 322→
 323→  const handleSearchChange = useCallback((val: string) => {
 324→    setSearchQuery(val);
 325→    setCurrentPage(1);
 326→  }, []);
 327→
 328→  const handleFilterChange = useCallback((val: string) => {
 329→    setStatusFilter(val);
 330→    setCurrentPage(1);
 331→  }, []);
 332→
 333→  const handleAdd = useCallback(() => {
 334→    if (!newEmail.trim() || !newZipCode.trim()) return;
 335→    const fd = new FormData();
 336→    fd.set("intent", "add");
 337→    fd.set("email", newEmail);
 338→    fd.set("zipCode", newZipCode);
 339→    fd.set("note", newNote);
 340→    fetcher.submit(fd, { method: "POST" });
 341→  }, [newEmail, newZipCode, newNote, fetcher]);
 342→
 343→  const handleDelete = useCallback(
 344→    (id: string) => {
 345→      const fd = new FormData();
 346→      fd.set("intent", "delete");
 347→      fd.set("id", id);
 348→      fetcher.submit(fd, { method: "POST" });
 349→    },
 350→    [fetcher],
 351→  );
 352→
 353→  const handleStatusChange = useCallback(
 354→    (id: string, status: string) => {
 355→      const fd = new FormData();
 356→      fd.set("intent", "update-status");
 357→      fd.set("id", id);
 358→      fd.set("status", status);
 359→      fetcher.submit(fd, { method: "POST" });
 360→    },
 361→    [fetcher],
 362→  );
 363→
 364→  useEffect(() => {
 365→    if (fetcher.state === "idle" && fetcher.data) {
 366→      if ("success" in fetcher.data && fetcher.data.success) {
 367→        const fetcherAction =
 368→          "action" in fetcher.data ? fetcher.data.action : "";
 369→        if (fetcherAction === "added") {
 370→          shopify.toast.show("Added to waitlist");
 371→          setAddModalOpen(false);
 372→          setNewEmail("");
 373→          setNewZipCode("");
 374→          setNewNote("");
 375→        } else if (fetcherAction === "deleted") {
 376→          shopify.toast.show("Entry removed");
 377→        } else if (fetcherAction === "updated") {
 378→          shopify.toast.show("Status updated");
 379→        } else if (fetcherAction === "accepted") {
 380→          shopify.toast.show("ZIP code accepted and added to allowed list");
 381→        } else if (fetcherAction === "rejected") {
 382→          shopify.toast.show("Request rejected");
 383→        } else if (fetcherAction === "deleted-notified") {
 384→          shopify.toast.show("Notified entries cleared");
 385→        }
 386→      }
 387→    }
 388→  }, [fetcher.state, fetcher.data, shopify]);
 389→
 390→  const handleBulkNotify = useCallback(() => {
 391→    if (!notifyZip.trim()) return;
 392→    const fd = new FormData();
 393→    fd.set("intent", "notify-zip");
 394→    fd.set("zipCode", notifyZip);
 395→    fetcher.submit(fd, { method: "POST" });
 396→    setNotifyModalOpen(false);
 397→    setNotifyZip("");
 398→  }, [notifyZip, fetcher]);
 399→
 400→  const handleCopyEmails = useCallback(() => {
 401→    if (!notifyResult) return;
 402→    navigator.clipboard.writeText(notifyResult.emails.join(", ")).then(() => {
 403→      setCopySuccess(true);
 404→      setTimeout(() => setCopySuccess(false), 2000);
 405→    });
 406→  }, [notifyResult]);
 407→
 408→  const handleDeleteNotified = useCallback(() => {
 409→    const fd = new FormData();
 410→    fd.set("intent", "delete-all-notified");
 411→    fetcher.submit(fd, { method: "POST" });
 412→  }, [fetcher]);
 413→
 414→  const handleAccept = useCallback(
 415→    (id: string) => {
 416→      const fd = new FormData();
 417→      fd.set("intent", "accept");
 418→      fd.set("id", id);
 419→      fetcher.submit(fd, { method: "POST" });
 420→    },
 421→    [fetcher],
 422→  );
 423→
 424→  const handleReject = useCallback(
 425→    (id: string) => {
 426→      const fd = new FormData();
 427→      fd.set("intent", "reject");
 428→      fd.set("id", id);
 429→      fetcher.submit(fd, { method: "POST" });
 430→    },
 431→    [fetcher],
 432→  );
 433→
 434→  // Compute per-ZIP waiting counts for the "Notify Waitlist" section
 435→  const zipWaitingCounts = useMemo(() => {
 436→    const map = new Map<string, number>();
 437→    for (const e of entries as WaitlistEntry[]) {
 438→      if (e.status === "waiting") {
 439→        map.set(e.zipCode, (map.get(e.zipCode) ?? 0) + 1);
 440→      }
 441→    }
 442→    return Array.from(map.entries())
 443→      .map(([zipCode, count]) => ({ zipCode, count }))
 444→      .sort((a, b) => b.count - a.count);
 445→  }, [entries]);
 446→
 447→  const handleNotifyZip = useCallback(
 448→    (zipCode: string) => {
 449→      const fd = new FormData();
 450→      fd.set("intent", "notify-zip");
 451→      fd.set("zipCode", zipCode);
 452→      fetcher.submit(fd, { method: "POST" });
 453→    },
 454→    [fetcher],
 455→  );
 456→
 457→  if (isFreePlan) {
 458→    return (
 459→      <Page
 460→        title="Customer Waitlist"
 461→        subtitle="Customers waiting for delivery availability in their area"
 462→        backAction={{ onAction: () => navigate("/app") }}
 463→      >
 464→        <Layout>
 465→          <Layout.Section>
 466→            <Banner
 467→              tone="info"
 468→              title="Waitlist requires Starter plan or higher"
 469→              action={{ content: "View pricing plans", url: "/app/pricing" }}
 470→            >
 471→              <Text as="p">
 472→                The customer waitlist feature is not available on the Free plan.
 473→                Upgrade to Starter to collect up to 25 waitlist entries, or upgrade
 474→                to Pro or Ultimate for unlimited entries and bulk notify.
 475→              </Text>
 476→            </Banner>
 477→          </Layout.Section>
 478→        </Layout>
 479→      </Page>
 480→    );
 481→  }
 482→
 483→  const statusOptions = [
 484→    { label: "Waiting", value: "waiting" },
 485→    { label: "Accepted", value: "accepted" },
 486→    { label: "Rejected", value: "rejected" },
 487→    { label: "Notified", value: "notified" },
 488→    { label: "Converted", value: "converted" },
 489→  ];
 490→
 491→  const filterOptions = [
 492→    { label: "All", value: "all" },
 493→    { label: "Waiting", value: "waiting" },
 494→    { label: "Accepted", value: "accepted" },
 495→    { label: "Rejected", value: "rejected" },
 496→    { label: "Notified", value: "notified" },
 497→    { label: "Converted", value: "converted" },
 498→  ];
 499→
 500→  const formatDate = (d: string | Date) => {
 501→    const date = new Date(d);
 502→    return date.toLocaleDateString("en-US", {
 503→      month: "short",
 504→      day: "numeric",
 505→      year: "numeric",
 506→    });
 507→  };
 508→
 509→  const tableRows = paginatedEntries.map((entry) => [
 510→    <BlockStack gap="050" key={`name-${entry.id}`}>
 511→      <Text as="span" fontWeight="semibold">
 512→        {entry.name || "—"}
 513→      </Text>
 514→      <Text as="span" variant="bodySm" tone="subdued">
 515→        {entry.email}
 516→      </Text>
 517→    </BlockStack>,
 518→    <Text as="span" fontWeight="bold" key={`zip-${entry.id}`}>
 519→      {entry.zipCode}
 520→    </Text>,
 521→    <Box key={`status-${entry.id}`} minWidth="120px">
 522→      <Select
 523→        label="Status"
 524→        labelHidden
 525→        options={statusOptions}
 526→        value={entry.status}
 527→        onChange={(val) => handleStatusChange(entry.id, val)}
 528→      />
 529→    </Box>,
 530→    formatDate(entry.createdAt),
 531→    <InlineStack gap="200" key={`actions-${entry.id}`} wrap={false}>
 532→      {entry.status === "waiting" && (
 533→        <>
 534→          <Tooltip content="Accept — adds ZIP to allowed list">
 535→            <Button
 536→              size="slim"
 537→              tone="success"
 538→              onClick={() => handleAccept(entry.id)}
 539→            >
 540→              Accept
 541→            </Button>
 542→          </Tooltip>
 543→          <Tooltip content="Reject this request">
 544→            <Button
 545→              size="slim"
 546→              tone="critical"
 547→              onClick={() => handleReject(entry.id)}
 548→            >
 549→              Reject
 550→            </Button>
 551→          </Tooltip>
 552→        </>
 553→      )}
 554→      <Tooltip content="Remove from waitlist">
 555→        <Button
 556→          size="slim"
 557→          variant="tertiary"
 558→          tone="critical"
 559→          onClick={() => handleDelete(entry.id)}
 560→          icon={DeleteIcon}
 561→          accessibilityLabel="Delete"
 562→        />
 563→      </Tooltip>
 564→    </InlineStack>,
 565→  ]);
 566→
 567→  return (
 568→    <Page
 569→      title="Customer Waitlist"
 570→      subtitle="Customers waiting for delivery availability in their area"
 571→      backAction={{ onAction: () => navigate("/app") }}
 572→      primaryAction={
 573→        isStarterPlan && stats.total >= limits.maxWaitlist
 574→          ? {
 575→              content: "Upgrade to Add More",
 576→              onAction: () => navigate("/app/pricing"),
 577→            }
 578→          : {
 579→              content: "Add Entry",
 580→              icon: PlusIcon,
 581→              onAction: () => setAddModalOpen(true),
 582→            }
 583→      }
 584→      secondaryActions={
 585→        !isStarterPlan
 586→          ? [
 587→              {
 588→                content: "Notify by ZIP",
 589→                icon: EmailIcon,
 590→                onAction: () => setNotifyModalOpen(true),
 591→              },
 592→            ]
 593→          : undefined
 594→      }
 595→    >
 596→      <Box paddingBlockEnd="1600">
 597→      <Layout>
 598→        {/* Stats */}
 599→        <Layout.Section>
 600→          <InlineGrid columns={{ xs: 2, sm: 2, md: 5 }} gap="400">
 601→            <Box
 602→              padding="400"
 603→              background="bg-surface"
 604→              borderWidth="025"
 605→              borderColor="border"
 606→              borderRadius="200"
 607→            >
 608→              <BlockStack gap="100">
 609→                <Text as="p" tone="subdued" variant="bodySm">
 610→                  Total
 611→                </Text>
 612→                <Text as="p" variant="headingXl" fontWeight="bold">
 613→                  {stats.total}
 614→                </Text>
 615→              </BlockStack>
 616→            </Box>
 617→            <Box
 618→              padding="400"
 619→              background="bg-surface-warning"
 620→              borderWidth="025"
 621→              borderColor="border-warning"
 622→              borderRadius="200"
 623→            >
 624→              <BlockStack gap="100">
 625→                <Text as="p" tone="caution" variant="bodySm">
 626→                  Waiting
 627→                </Text>
 628→                <Text as="p" variant="headingXl" fontWeight="bold" tone="caution">
 629→                  {stats.waiting}
 630→                </Text>
 631→              </BlockStack>
 632→            </Box>
 633→            <Box
 634→              padding="400"
 635→              background="bg-surface-info"
 636→              borderWidth="025"
 637→              borderColor="border-info"
 638→              borderRadius="200"
 639→            >
 640→              <BlockStack gap="100">
 641→                <Text as="p" tone="subdued" variant="bodySm">
 642→                  Notified
 643→                </Text>
 644→                <Text as="p" variant="headingXl" fontWeight="bold">
 645→                  {stats.notified}
 646→                </Text>
 647→              </BlockStack>
 648→            </Box>
 649→            <Box
